import boto3
from datetime import datetime, timedelta

def compare_metric_data(
    metric_name: str,
    namespace: str,
    dimension_filter1: list[dict], # e.g., [{'Name': 'InstanceId', 'Value': 'i-0abcdef1234567890'}]
    dimension_filter2: list[dict],
    statistic: str, # e.g., 'Average', 'Sum', 'Maximum', 'Minimum', 'SampleCount'
    period_seconds: int, # in seconds, e.g., 300 for 5 minutes
    start_time: datetime,
    end_time: datetime,
    region_name: str = 'us-east-1'
) -> dict:
    """
    Compares metric values for two resources or dimension filters over the same window
    using Amazon CloudWatch Metrics.

    Args:
        metric_name: The name of the metric to retrieve (e.g., 'CPUUtilization').
        namespace: The namespace of the metric (e.g., 'AWS/EC2').
        dimension_filter1: A list of dimension dictionaries for the first resource/filter.
        dimension_filter2: A list of dimension dictionaries for the second resource/filter.
        statistic: The statistic to apply to the metric data (e.g., 'Average').
        period_seconds: The granularity of the returned data, in seconds.
        start_time: The start of the time range to retrieve data for.
        end_time: The end of the time range to retrieve data for.
        region_name: The AWS region to connect to.

    Returns:
        A dictionary containing the metric data points for both filters,
        with keys 'filter1_data' and 'filter2_data'. Each will contain a list of
        dictionaries with 'Timestamp' and 'Value'.
    """
    cloudwatch = boto3.client('cloudwatch', region_name=region_name)

    metric_data_queries = [
        {
            'Id': 'filter1',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': dimension_filter1
                },
                'Period': period_seconds,
                'Stat': statistic
            },
            'ReturnData': True,
            'Label': 'Filter 1 Data'
        },
        {
            'Id': 'filter2',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': dimension_filter2
                },
                'Period': period_seconds,
                'Stat': statistic
            },
            'ReturnData': True,
            'Label': 'Filter 2 Data'
        }
    ]

    response = cloudwatch.get_metric_data(
        MetricDataQueries=metric_data_queries,
        StartTime=start_time,
        EndTime=end_time,
        ScanBy='TimestampAscending'
    )

    filter1_results = []
    filter2_results = []

    for result in response['MetricDataResults']:
        if result['Id'] == 'filter1':
            for i in range(len(result.get('Timestamps', []))):
                filter1_results.append({
                    'Timestamp': result['Timestamps'][i],
                    'Value': result['Values'][i]
                })
        elif result['Id'] == 'filter2':
            for i in range(len(result.get('Timestamps', []))):
                filter2_results.append({
                    'Timestamp': result['Timestamps'][i],
                    'Value': result['Values'][i]
                })

    return {
        'filter1_data': filter1_results,
        'filter2_data': filter2_results
    }
